// recoverybox-mesh.js
// MANAGED BY ANSIBLE, DO NOT EDIT THIS FILE MANUALLY
(function() {
    let mapInstance = null;
    let meshMarkers = {}; // Storage of markers by node ID

    // Custom icon for radio nodes
    const meshIcon = L.icon({
        iconUrl: 'mesh-node.png', // Create an icon or reuse the existing one
        iconSize: [23, 38],
        iconAnchor: [12, 38],
        popupAnchor: [0, -38]
    });

    function formatEpochTimestamp(value) {
        if (value === null || value === undefined || value === "") return "Unknown";

        const timestamp = Number(value);
        if (!Number.isFinite(timestamp)) return "Unknown";

        const normalizedTimestamp = timestamp.toString().length < 13 ? timestamp * 1000 : timestamp;

        return new Date(normalizedTimestamp).toLocaleString("fr-FR", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit"
        });
    }

    function updateMeshPositions() {
        if (!mapInstance) return;

        fetch('meshtastic_nodes.json?t=' + new Date().getTime())
            .then(response => {
                if (!response.ok) throw new Error("Mesh node JSON file is not available");
                return response.json();
            })
            .then(data => {
                if (data.features) {
                    // List of IDs present in this refresh to clean up disconnected nodes if needed
                    let activeIds = [];

                    data.features.forEach(feature => {
                        const props = feature.properties;
                        const lon = feature.geometry.coordinates[0];
                        const lat = feature.geometry.coordinates[1];
                        const pos = [lat, lon];
                        const nodeId = props.id;
                        activeIds.push(nodeId);
                        console.log("RecoveryBox Mesh - Position lue :", pos);


                        const popupContent = `<b>Node: ${props.name}</b><br>
                                              ID: ${props.id}<br>
                                              Battery: ${props.battery}%<br>
                                              SNR: ${props.snr}<br>
                                              Last contact: ${formatEpochTimestamp(props.lastHeard)}`;

                        if (!meshMarkers[nodeId]) {
                            // Create the marker if it does not exist
                            meshMarkers[nodeId] = L.marker(pos, { icon: meshIcon }).addTo(mapInstance);
                            meshMarkers[nodeId].bindPopup(popupContent);
                        } else {
                            // Update the position and popup if the node has moved
                            meshMarkers[nodeId].setLatLng(pos);
                            meshMarkers[nodeId].setPopupContent(popupContent);
                        }
                    });
                }
            })
            .catch(err => console.log("RecoveryBox Mesh tracking error:", err));
    }

    function hookLeafletMesh() {
        if (typeof L !== 'undefined' && L.Map) {
            console.log("RecoveryBox Mesh: Leaflet detected.");
            
            L.Map.addInitHook(function () {
                mapInstance = this;
                console.log("RecoveryBox Mesh : Instance de la carte interceptée avec succès !");

                
                // Immediate first call
                updateMeshPositions();
                // Refresh aligned with the Bash script (every 60s)
                setInterval(updateMeshPositions, 60000);
            });
        } else {
            setTimeout(hookLeafletMesh, 100);
        }
    }

    hookLeafletMesh();
})();